def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    for i in range(n):
        if opp[i] == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if me[i] == 'C':
            my_c += 1
        else:
            my_d += 1

    # Near the end, exploit sufficiently cooperative partners; defend otherwise.
    if n >= 90:
        if opp_d <= 2:
            if n == 99:
                return 'D'
            if opp[-1] == 'C' and rng.random() < 0.55:
                return 'D'
            return 'C'
        if opp_d * 3 <= n:
            if opp[-1] == 'C' and rng.random() < 0.7:
                return 'D'
            if opp[-1] == 'D' and rng.random() < 0.25:
                return 'C'
            return 'D'
        if opp_d * 2 >= n:
            return 'D'
        if opp[-1] == 'C' and rng.random() < 0.4:
            return 'C'
        return 'D'

    # Pure cooperator: keep the long cooperative stream, with rare exploitation.
    if opp_d == 0:
        if n >= 20 and rng.random() < 0.035:
            return 'D'
        return 'C'

    # Pure or heavy defector: protect, but occasionally test for re-entry.
    if opp_c == 0:
        if n >= 8 and rng.random() < 0.07:
            return 'C'
        return 'D'
    if opp_d >= opp_c + 4:
        if opp[-1] == 'C' and rng.random() < 0.6:
            return 'C'
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # If opponent defected only once in an otherwise cooperative match, forgive.
    if opp_d == 1 and n >= 6:
        if opp[-1] == 'C':
            return 'C'
        if rng.random() < 0.75:
            return 'C'
        return 'D'

    last_me = me[-1]
    last_opp = opp[-1]

    recent_len = 8 if n >= 8 else n
    recent_opp_d = 0
    recent_opp_c = 0
    recent_me_d = 0
    recent_cc = 0
    for i in range(n - recent_len, n):
        if opp[i] == 'D':
            recent_opp_d += 1
        else:
            recent_opp_c += 1
        if me[i] == 'D':
            recent_me_d += 1
        if me[i] == 'C' and opp[i] == 'C':
            recent_cc += 1

    # If mutual defection dominates recently, make a conciliatory move.
    if recent_opp_d >= 4 and recent_me_d >= 3 and recent_cc == 0:
        if rng.random() < 0.7:
            return 'C'

    # If we have defected much more than the opponent, repair the relationship.
    if my_d > opp_d + 3 and opp[-1] == 'C':
        return 'C'

    if last_opp == 'D':
        # Punish defections, but forgive if recent behavior is mostly cooperative.
        if recent_opp_c >= recent_len - 2 and rng.random() < 0.45:
            return 'C'
        if recent_opp_d >= 4:
            return 'D'
        # Alternating retaliation breaker: cooperate after our own defection sometimes.
        if last_me == 'D' and rng.random() < 0.4:
            return 'C'
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Opponent cooperated last: preserve cooperation, probe rarely.
    if n > 10 and rng.random() < 0.025:
        return 'D'
    if opp_d >= 3 and opp_d * 2 >= n and rng.random() < 0.2:
        return 'D'
    return 'C'
